import{_ as e,o as l,c as t,a5 as i}from"./chunks/framework.DJo0M80U.js";const _=JSON.parse('{"title":"哈希算法","description":"哈希算法是指把任意长度的二进制映射为固定长度的较小的二进制值，这个较小的二进制值叫做哈希值。 什么是链表 链表是可以将物理地址上不连续的数据连接起来，通过指针来对物理地址进行操作，实现增删改查等功能。 链表大致分为单链表和双向链表 单链表:每个节点包含两部分,一部分存放数据变量的。","frontmatter":{"title":"哈希算法","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","Java 面试"],"description":"哈希算法是指把任意长度的二进制映射为固定长度的较小的二进制值，这个较小的二进制值叫做哈希值。 什么是链表 链表是可以将物理地址上不连续的数据连接起来，通过指针来对物理地址进行操作，实现增删改查等功能。 链表大致分为单链表和双向链表 单链表:每个节点包含两部分,一部分存放数据变量的。","sidebarWeight":9,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/java/集合类型/哈希算法.md"},"headers":[],"relativePath":"posts/前端面试与实战/04-Java 面试/集合类型/哈希算法.md","filePath":"posts/前端面试与实战/04-Java 面试/集合类型/哈希算法.md"}'),s={name:"posts/前端面试与实战/04-Java 面试/集合类型/哈希算法.md"};function p(o,a,n,r,h,d){return l(),t("div",null,[...a[0]||(a[0]=[i('<div><h1 id="哈希算法" tabindex="-1">哈希算法 <a class="header-anchor" href="#哈希算法" aria-label="Permalink to &quot;哈希算法&quot;">​</a></h1><blockquote><p>本节目标：理解“哈希算法”的核心思路，并能把它用于实际开发或面试表达。</p></blockquote><blockquote><p>说明：原 OneNote 中有图片引用，但图片未包含在导出目录中；本页保留了可用的文字与代码内容。 哈希算法是指把任意长度的二进制映射为固定长度的较小的二进制值，这个较小的二进制值叫做哈希值。</p></blockquote><p>什么是链表</p><ul><li>链表是可以将物理地址上不连续的数据连接起来，通过指针来对物理地址进行操作，实现增删改查等功能。</li><li>链表大致分为单链表和双向链表</li></ul><p>单链表:每个节点包含两部分,一部分存放数据变量的data,另一部分是指向下一节点的next指针</p><p>双向链表:除了包含单链表的部分,还增加的pre前一个节点的指针</p><p>链表的优点</p><ul><li>插入删除速度快（因为有next指针指向其下一个节点，通过改变指针的指向可以方便的增加删除元素）</li><li>内存利用率高，不会浪费内存（可以使用内存中细小的不连续空间（大于node节点的大小），并且在需要空间的时候才创建空间）</li><li>大小没有固定，拓展很灵活。</li></ul><p>链表的缺点 不能随机查找，必须从第一个开始遍历，查找效率低。</p><p>说一下HashMap的实现原理？</p><ul><li>HashMap概述： HashMap是基于哈希表的Map接口的非同步实现。此实现提供所有可选的映射操作，并允许使用null值和null键。此类不保证映射的顺序，特别是它不保证该顺序恒久不变。</li><li>HashMap的数据结构： 在Java编程语言中，最基本的结构就是两种，一个是数组，另外一个是模拟指针（引用），所有的数据结构都可以用这两个基本结构来构造的，HashMap也不例外。HashMap实际上是一个“链表散列”的数据结构，即数组和链表的结合体。</li></ul><p>HashMap 基于 Hash 算法实现的</p><ul><li>当我们往HashMap中put元素时，利用key的hashCode重新hash计算出当前对象的元素在数组中的下标</li><li>存储时，如果出现hash值相同的key，此时有两种情况。</li><li>​ (1)如果key相同，则覆盖原始值；</li><li>​ (2)如果key不同（出现冲突），则将当前的key-value放入链表中</li><li>获取时，直接找到hash值对应的下标，在进一步判断key是否相同，从而找到对应值。</li><li>理解了以上过程就不难明白HashMap是如何解决hash冲突的问题，核心就是使用了数组的存储方式，然后将冲突的key的对象放入链表中，一旦发现冲突就在链表中做进一步的对比。</li><li>需要注意Jdk 1.8中对HashMap的实现做了优化，当链表中的节点数据超过八个之后，该链表会转为红黑树来提高查询效率，从原来的O(n)到O(logn)</li></ul></div>',1)])])}const c=e(s,[["render",p]]);export{_ as __pageData,c as default};
